remote_state {
  backend = "local"
  config = {
    path = "${get_parent_terragrunt_dir()}/.state/${path_relative_to_include()}/terraform.tfstate"
  }
  generate = {
    path      = "backend.tf"
    if_exists = "overwrite_terragrunt"
  }
}

# Inputs every unit receives.
inputs = {
  name_prefix = local.account.locals.name_prefix
  tags        = local.account.locals.tags
}

