mkdir -p ~/academy-labs/p4-2 && cd ~/academy-labs/p4-2
mkdir -p modules/vpc modules/pool modules/bucket
cat > modules/vpc/main.tf <<'EOF'
variable "name_prefix" { type = string }
variable "vpc_cidr" { type = string }
variable "tags" { type = map(string) }

resource "terraform_data" "vpc" {
  input = { name = "${var.name_prefix}-vpc", cidr = var.vpc_cidr, tags = var.tags }
}

output "private_subnets" {
  value = [for n in range(3) : cidrsubnet(var.vpc_cidr, 2, n)]
}
EOF
cat > modules/pool/main.tf <<'EOF'
variable "name_prefix" { type = string }
variable "subnet_ids" { type = list(string) }
variable "sizes" { type = map(string) }
variable "tags" { type = map(string) }

resource "terraform_data" "group" {
  for_each = var.sizes
  input    = { name = "${var.name_prefix}-sandbox-${each.key}", type = each.value, subnets = var.subnet_ids }
}
EOF
cat > modules/bucket/main.tf <<'EOF'
variable "bucket_name" { type = string }
variable "tags" { type = map(string) }

resource "terraform_data" "bucket" {
  input = { name = var.bucket_name, tags = var.tags }
}
EOF
